INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100001, 2, 1, '', '&lt;p&gt;Stand on the stump near the Kokiri Forest entrance and play Saria&#039;s Song for the Skull Kid.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Fairy Ocarina, Saria&#039;s Song&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100001);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100002, 2, 1, '', '&lt;p&gt;Beat the Skull Kids&#039; ocarina memory game three rounds in a row, near the target tree.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Fairy Ocarina&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100002);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100003, 2, 1, '', '&lt;p&gt;Inside the ranch tower: move the crates and crawl through the gap to a hidden room.&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100003);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100004, 2, 1, '', '&lt;p&gt;Blow open the hidden hole just outside Castle Town and buy it from the Business Scrub. A Fairy Note gives the password.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Bombs, 100 Rupees&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100004);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100005, 2, 1, '', '&lt;p&gt;A chest under large rocks near the Gerudo Valley arch. Read the Fairy Note as Adult Link, then collect it as Young Link.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Fairy Note&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100005);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100006, 2, 1, '', '&lt;p&gt;At night, find the white dog Richard in Castle Town and bring him back to his owner in the back alley.&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100006);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100007, 2, 1, '', '&lt;p&gt;A prize in the Treasure Chest Shop game, open at night. The Lens of Truth makes it easy.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; 10 Rupees per game&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100007);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100008, 2, 1, '', '&lt;p&gt;One of the Bombchu Bowling Alley prizes.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Bombchus, 30 Rupees per game&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100008);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100009, 2, 1, '', '&lt;p&gt;Reward for bringing 50 Gold Skulltula Tokens to the cursed family in the House of Skulltula.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; 50 Gold Skulltula Tokens&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100009);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100010, 2, 1, '', '&lt;p&gt;On the ledge inside the windmill, reached from the turning platform.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Hookshot (from Damp&eacute;&#039;s race)&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100010);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100011, 2, 1, '', '&lt;p&gt;Talk to the man sitting on the blue roof by the windmill. Glide over with a Cucco, or Hookshot onto the vines.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Cucco or Hookshot&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100011);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100012, 2, 1, '', '&lt;p&gt;On the rooftop where Kaepora Gaebora drops you after flying you down from Death Mountain.&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100012);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100013, 2, 1, '', '&lt;p&gt;At night, pay Damp&eacute; to dig in the graveyard&#039;s soft soil until he turns up something hard.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; 10 Rupees per dig&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100013);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100014, 2, 1, '', '&lt;p&gt;Pull back the southernmost tombstone in the right-hand row at night and drop in. The chest is right there, with no song or enemies needed.&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100014);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100015, 2, 1, '', '&lt;p&gt;On the high ruins in the graveyard. Plant a Magic Bean in the soil there as Young Link and ride the flower as Adult Link.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Magic Bean&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100015);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100016, 2, 1, '', '&lt;p&gt;Race Damp&eacute; through his tomb again and finish in under a minute.&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100016);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100017, 2, 1, '', '&lt;p&gt;In an opening above the Dodongo&#039;s Cavern entrance. Ride the Magic Bean flower planted just outside.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Magic Bean&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100017);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100018, 2, 1, '', '&lt;p&gt;Light the torches around the big pot, then drop a lit bomb into it from above to stop it on the right face.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Bombs or a Bomb Flower&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100018);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100019, 2, 1, '', '&lt;p&gt;Climb down the netting on the cliff straight ahead as you enter the crater from the trail.&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100019);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100020, 2, 1, '', '&lt;p&gt;Plant a Magic Bean by the warp pad as Young Link, then ride the flower as Adult Link to the piece in the smoke.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Magic Bean, Bolero of Fire&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100020);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100021, 2, 1, '', '&lt;p&gt;Buy it from the Business Scrub on the lower ledge on the left.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; 100 Rupees&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100021);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100022, 2, 1, '', '&lt;p&gt;On a raised platform partway up the river. Glide there with the Cucco from the Hyrule Field end.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Cucco&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100022);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100023, 2, 1, '', '&lt;p&gt;On a high ledge near the waterfall at the top of the river. Carry the Cucco up and glide across.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Cucco&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100023);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100024, 2, 1, '', '&lt;p&gt;Play the Song of Storms to the frogs on the log.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Song of Storms&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100024);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100025, 2, 1, '', '&lt;p&gt;Win the frogs&#039; ocarina game after growing all five frogs with your songs.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; All the songs you&#039;ve learned&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100025);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100026, 2, 1, '', '&lt;p&gt;Light every torch around the waterfall to make a chest appear.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Deku Stick&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100026);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100027, 2, 1, '', '&lt;p&gt;On the farthest of the floating ice platforms in the frozen fountain.&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100027);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100028, 2, 1, '', '&lt;p&gt;On the bottom of the fountain near the Ice Cavern entrance.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Iron Boots, Zora Tunic&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100028);
