INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100030, 2, 1, '', '&lt;p&gt;Dive to the bottom of the laboratory tank, then talk to the scientist.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Golden Scale&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100030);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100031, 2, 1, '', '&lt;p&gt;On top of the laboratory tower. Ride the Magic Bean flower planted outside.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Magic Bean&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100031);
