INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64100033, 2, 1, '', '&lt;p&gt;Behind the waterfall: drop to the ledge below and follow the path north.&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young or Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64100033);
