INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64200005, 2, 1, '', '&lt;p&gt;In the bug hole in the Deku Scrub clearing.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Bugs in a bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Young Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64200005);
