INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300001, 2, 1, '', '&lt;p&gt;Behind the stone Hyrule sign just outside Castle Town, on the road to Lon Lon Ranch. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300001);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300002, 2, 1, '', '&lt;p&gt;Along the moat, just right of the Castle Town exit. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300002);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300003, 2, 1, '', '&lt;p&gt;Farther along the Lon Lon Ranch road, near the ranch entrance, by the fence with a purple lantern. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300003);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300004, 2, 1, '', '&lt;p&gt;By a glowing overturned trunk on the east side of Lon Lon Ranch. Approach from the south. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300004);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300005, 2, 1, '', '&lt;p&gt;East of Gerudo Valley, by the low glowing wall on the incline to its entrance. Birds circle nearby. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300005);
