INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300007, 2, 1, '', '&lt;p&gt;South of Lon Lon Ranch, between the ranch fence and the Deku Scrub woods, by a ghostly branch with a lantern. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300007);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300008, 2, 1, '', '&lt;p&gt;East of the Lake Hylia entrance, by a fallen tree near the wetlands. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300008);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300009, 2, 1, '', '&lt;p&gt;Where the dry southwestern part of Hyrule Field meets the grassland, near the ruined tower at Lon Lon Ranch. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300009);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 64300010, 2, 1, '', '&lt;p&gt;On the hillside just south of the path into Kokiri Forest. Ride Epona and jump the spot to make it appear, then shoot it down and bottle it. Sell it to the Poe Collector in Castle Town.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Needs:&lt;/strong&gt; Epona, Fairy Bow, an empty bottle&lt;/p&gt;&lt;p&gt;&lt;em&gt;Adult Link&lt;/em&gt;&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 64300010);
